+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/elliott/ElliottScenarioGenerator.java
@@ -44,0 +45 @@ public final class ElliottScenarioGenerator {
+    private static final int MAX_DECOMPOSITION_PIVOTS = 16;
@@ -465 +466 @@ public final class ElliottScenarioGenerator {
-        final List<SwingPivotPoint> pivots = extractPivots(swings);
+        final List<SwingPivotPoint> pivots = limitPivotsForDecomposition(extractPivots(swings));
@@ -489 +490 @@ public final class ElliottScenarioGenerator {
-        final List<SwingPivotPoint> pivots = extractPivots(swings);
+        final List<SwingPivotPoint> pivots = limitPivotsForDecomposition(extractPivots(swings));
@@ -531,0 +533,46 @@ public final class ElliottScenarioGenerator {
+    private List<SwingPivotPoint> limitPivotsForDecomposition(final List<SwingPivotPoint> pivots) {
+        if (pivots.size() <= MAX_DECOMPOSITION_PIVOTS) {
+            return pivots;
+        }
+
+        final List<SwingPivotPoint> limited = new ArrayList<>(MAX_DECOMPOSITION_PIVOTS);
+        limited.add(pivots.getFirst());
+
+        final int internalTarget = MAX_DECOMPOSITION_PIVOTS - 2;
+        final int internalSourceCount = pivots.size() - 2;
+        final boolean[] selected = new boolean[pivots.size()];
+        selected[0] = true;
+        selected[pivots.size() - 1] = true;
+
+        for (int slot = 0; slot < internalTarget; slot++) {
+            final double fraction = (slot + 1.0) / (internalTarget + 1.0);
+            int sourceIndex = 1 + (int) Math.round(fraction * (internalSourceCount - 1));
+            sourceIndex = Math.max(1, Math.min(pivots.size() - 2, sourceIndex));
+            while (selected[sourceIndex] && sourceIndex < pivots.size() - 2) {
+                sourceIndex++;
+            }
+            while (selected[sourceIndex] && sourceIndex > 1) {
+                sourceIndex--;
+            }
+            if (selected[sourceIndex]) {
+                continue;
+            }
+            selected[sourceIndex] = true;
+        }
+
+        for (int index = 1; index < pivots.size() - 1 && limited.size() < MAX_DECOMPOSITION_PIVOTS - 1; index++) {
+            if (selected[index]) {
+                limited.add(pivots.get(index));
+            }
+        }
+        for (int index = 1; index < pivots.size() - 1 && limited.size() < MAX_DECOMPOSITION_PIVOTS - 1; index++) {
+            if (!selected[index]) {
+                limited.add(pivots.get(index));
+            }
+        }
+
+        limited.sort(java.util.Comparator.comparingInt(SwingPivotPoint::index));
+        limited.add(pivots.getLast());
+        return List.copyOf(limited);
+    }
+
diff --git a/ta4j-core/src/main/java/org/ta4j/core/indicators/elliott/swing/SwingDetectorSupport.java b/ta4j-core/src/main/java/org/ta4j/core/indicators/elliott/swing/SwingDetectorSupport.java
index da71eeb61..0d2adacee 100644
--- a/ta4j-core/src/main/java/org/ta4j/core/indicators/elliott/swing/SwingDetectorSupport.java
+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/elliott/swing/SwingDetectorSupport.java
@@ -67,2 +67,15 @@ final class SwingDetectorSupport {
-        final List<SwingPivot> normalized = new ArrayList<>(sorted.size());
-        for (final SwingPivot pivot : sorted) {
+        final List<SwingPivot> byIndex = new ArrayList<>(sorted.size());
+        int position = 0;
+        while (position < sorted.size()) {
+            final int currentIndex = sorted.get(position).index();
+            SwingPivot resolved = sorted.get(position);
+            position++;
+            while (position < sorted.size() && sorted.get(position).index() == currentIndex) {
+                resolved = chooseSharedIndexPivot(byIndex, resolved, sorted.get(position));
+                position++;
+            }
+            byIndex.add(resolved);
+        }
+
+        final List<SwingPivot> normalized = new ArrayList<>(byIndex.size());
+        for (final SwingPivot pivot : byIndex) {
@@ -82,0 +96,25 @@ final class SwingDetectorSupport {
+    private static SwingPivot chooseSharedIndexPivot(final List<SwingPivot> normalized, final SwingPivot existing,
+            final SwingPivot candidate) {
+        if (existing == null) {
+            return candidate;
+        }
+        if (candidate == null) {
+            return existing;
+        }
+        if (existing.type() == candidate.type()) {
+            return chooseMoreExtreme(existing, candidate);
+        }
+        if (normalized.size() >= 2) {
+            final Num anchor = normalized.get(normalized.size() - 2).price();
+            if (!Num.isNaNOrNull(anchor)) {
+                final Num existingDistance = existing.price().minus(anchor).abs();
+                final Num candidateDistance = candidate.price().minus(anchor).abs();
+                return candidateDistance.isGreaterThan(existingDistance) ? candidate : existing;
+            }
+        }
+        if (existing.type() == SwingPivotType.HIGH || candidate.type() == SwingPivotType.LOW) {
+            return existing.price().isGreaterThan(candidate.price()) ? existing : candidate;
+        }
+        return existing.price().isLessThan(candidate.price()) ? existing : candidate;
+    }
+
